/**
 * The 69 jurisdictions that issue a North American driver's license: 50 US states,
 * the District of Columbia, 5 US territories, and 13 Canadian provinces and
 * territories.
 *
 * Outlines come from the public-domain "BlankMap-USA-states-Canada-provinces" on
 * Wikimedia Commons, native box 2289x1744, with one deliberate distortion baked in.
 *
 * **The north is compressed to 72%.** Geographically Canada dwarfs the United
 * States, and on a true projection Nunavut and the Northwest Territories alone
 * outweigh the whole lower 48 — which badly misrepresents a post that counts
 * jurisdictions, not square kilometres. Every y below 968 (the northernmost
 * lower-48 ink, so the dividing line falls in empty Arctic rather than through any
 * US state) is pulled toward it:  y' = 968 - (968 - y) * 0.72. The map is otherwise
 * untouched, and because the transform is continuous and depends only on y, shared
 * borders stay exactly shared — no seams, no overlaps. To undo or retune it, invert
 * that formula against the Commons original. Alaska sits in its true position
 * beside Yukon — it has to, once Canada is on the map — and only Hawaii is inset,
 * at the bottom left. Paths use absolute M/L/C/z.
 *
 * Four of the five territories have no `d`: the source artwork does not draw them,
 * and at true scale Guam would be sub-pixel anyway. They render as labelled chips in
 * the empty Pacific at the bottom left.
 *
 * **Puerto Rico is an inset, drawn at 2.4x.** Its outline is the U.S. Census
 * generalised state boundary (public domain), projected equirectangular about
 * 18.22N and sized against the rest of the artwork, which measures 0.2365 units per
 * kilometre — checked two ways, Cape Sable to Boca Chica and Cape Mendocino to Cape
 * Sable, which agree to within half a percent. At true scale the island is 42x15
 * units, far too small to carry a label, and its true position is ~180 units below
 * the bottom of the viewport. So it sits in the Atlantic east-southeast of Florida,
 * the direction it really lies in, enlarged enough to label — the same licence
 * Hawaii's inset already takes. Vieques, Culebra and Mona are dropped: they would
 * land on top of the gutter leaders, and each is a few units across.
 *
 * `placement` decides how a jurisdiction is labelled:
 *   inline    — two-letter code set directly on the shape (55 of them)
 *   gutter    — too small to hold a label; chip in the Atlantic to the right, tied
 *               to the shape by a leader line
 *   offshore  — Hawaii only; chip beside its islands, none of which is big enough
 *   territory — no outline at all; chip in the bottom-left cluster (4 of them)
 *
 * Every inline anchor is the area-weighted centroid of that jurisdiction's largest
 * landmass, checked to fall inside its own outline.
 *
 * `issuance` records where the card is physically made. Only five jurisdictions in
 * North America still print at the counter — Delaware, Florida, Pennsylvania, the
 * U.S. Virgin Islands and Yukon — and Delaware is there on purpose, having taken
 * over $1M in federal grants to secure its offices rather than centralise. The
 * distinction matters to this post's argument: central issuance is how states
 * bought insider-threat resistance, and a signed barcode is the cryptographic
 * alternative to physically securing every counter.
 */
export type Placement = 'inline' | 'gutter' | 'offshore' | 'territory';

export interface Jurisdiction {
  /** Two-letter code, unique across both countries — there are no collisions. */
  code: string;
  name: string;
  country: 'US' | 'CA';
  /** Absent for the five territories, which the source artwork does not draw. */
  d?: string;
  /**
   * Label anchor for inline/offshore; leader-line origin for gutter. Zero for the
   * five territories, which the artwork does not place — JurisdictionMap lays those
   * out itself, and derives their popup anchor from that layout.
   */
  labelX: number;
  labelY: number;
  placement: Placement;
  /**
   * Optional render-time offset. Used only for Hawaii, whose inset the source
   * artwork parks far out in the Pacific — roughly 700 units of empty ocean from
   * anything else — which both strands the islands and forces the whole map to
   * carry that dead space. Moving the inset is legitimate: an inset's position is
   * already a cartographic choice, not a fact.
   */
  transform?: string;
  /**
   * Where the physical card is actually produced.
   *
   * 'central' — printed at a secure facility and mailed; the holder leaves the
   *             counter with a paper interim credential.
   * 'counter' — printed and handed over at the issuing office, same visit.
   *
   * Undefined for the Northern Mariana Islands and American Samoa, which publish
   * fee schedules and forms but no issuance procedure. That is a gap in the public
   * record, not a gap in this file.
   */
  issuance?: 'central' | 'counter';
}

/**
 * The drawn viewport, not the artwork's own 2289x1744 box. With Hawaii's inset
 * moved inland the westernmost ink is Alaska at x=542, so the first 500 units were
 * empty ocean; cropping them renders everything ~28% larger in the same column.
 */
export const NA_VIEW = { x: 500, y: 262.4, w: 1789, h: 1507.6 };

/** Gutter chips stack in this order, north to south, so leaders never cross. */
export const GUTTER_ORDER = ['PE', 'VT', 'NH', 'MA', 'RI', 'CT', 'NJ', 'DE', 'MD', 'DC'];

/** Territory chips stack in this order in the bottom-left cluster. */
export const TERRITORY_ORDER = ['VI', 'GU', 'MP', 'AS'];

